insert into baralho_ginga (id, dimensao, cor_hex, carta, definicao, pergunta) values
  ('G01', 'Governança', '#cc76a7', 'Quem puxa a roda', 'A liderança que articula mobiliza e mantém o ritmo colaborativo da equipe.', 'Conte um trabalho em parceria no qual faltou alguém para coordenar e manter o ritmo. Qual foi o desfecho?'),
  ('G02', 'Governança', '#cc76a7', 'Papel de cada um', 'A clareza de atribuições que faz o trabalho coletivo fluir sem sobreposições.', 'Conte uma vez em que a indefinição de papéis travou uma entrega relevante — ou em que a clareza destravou o processo.'),
  ('G03', 'Governança', '#cc76a7', 'Manda quem pode, obedece quem tem juízo?', 'Governança colaborativa: coordenar orientando o jogo sem autoritarismo.', 'Conte um projeto que prosperou sob liderança facilitadora — ou um que desandou pelo excesso de comando e controle.'),
  ('G04', 'Governança', '#cc76a7', 'Quando o chefe muda', 'A capacidade de transformar iniciativas em políticas institucionais perenes.', 'Conte um projeto que sobreviveu (ou foi descontinuado) em uma troca de gestão. O que fez a diferença para a continuidade?'),
  ('G05', 'Governança', '#cc76a7', 'Reinventar a roda', 'A falta de integração que faz equipes recriarem o que outros já resolveram.', 'Conte quando você descobriu que outro órgão já havia desenvolvido uma solução similar à que você estava criando.'),
  ('G06', 'Governança', '#cc76a7', 'Fio da meada', 'A gestão do conhecimento que documenta o processo e evita o recomeço do zero.', 'Conte quando a ausência de memória institucional fez o trabalho recomeçar do zero — ou quando uma boa documentação salvou tempo.'),
  ('G07', 'Governança', '#cc76a7', 'Destrava', 'Identificar os gargalos e acionar os atores certos para destravar o fluxo.', 'Conte um trabalho seu que emperrou na burocracia. Quem ajudou a destravar ou o que faltou para a decisão avançar?'),
  ('G08', 'Governança', '#cc76a7', 'Mãos dadas', 'O que extrapola sua competência direta se constrói por diálogo e pactuação.', 'Conte uma parceria entre órgãos ou equipes que prosperou por pactuação conjunta — ou uma que falhou por imposição de cima.'),
  ('G09', 'Governança', '#cc76a7', 'O cidadão no centro da roda', 'Governança pública legítima orientada pelo impacto real na vida do cidadão.', 'Conte uma decisão que mudou positivamente quando alguém perguntou como isso afeta o cidadão? — ou quando faltou essa pergunta.'),
  ('G10', 'Governança', '#cc76a7', 'Olho no lance', 'O acompanhamento estratégico que facilita entregas sem sufocar a autonomia.', 'Conte uma experiência de gestão que deu apoio e simplificou seu trabalho — ou uma que só gerou relatórios sem utilidade prática.'),
  ('I01', 'Incentivos', '#ebbe28', 'Semente', 'O apoio pequeno e oportuno (tempo verba ou aval) que faz a ideia germinar.', 'Conte uma semente que fez uma ideia original sua crescer. Ou a que faltou e o que teria mudado.'),
  ('I02', 'Incentivos', '#ebbe28', 'Brilho ou sangue no olho?', 'A diferença entre o reconhecimento que engaja e a sobrecarga que adoece.', 'Conte uma vez em que o comprometimento com o trabalho foi confundido com produtividade irreal e quais foram os impactos.'),
  ('I03', 'Incentivos', '#ebbe28', 'Para inglês ver', 'A inovação de fachada: celebrada no discurso mas sem efeitos na realidade.', 'Conte uma inovação de vitrine que você presenciou ou vivenciou. O que faltou para ela gerar transformação de verdade?'),
  ('I04', 'Incentivos', '#ebbe28', 'Tiro pela culatra', 'Quando o incentivo desenhado para premiar gera distorções ou desmotivação.', 'Conte uma tentativa de incentivo ou premiação que gerou efeito contrário ao esperado. O que deu errado no desenho?'),
  ('I05', 'Incentivos', '#ebbe28', 'Prata da casa', 'Valorizar e mobilizar a experiência e os talentos já presentes no órgão.', 'Conte quando um talento interno foi reconhecido e fez a diferença. Ou quando buscaram fora o que já existia dentro.'),
  ('I06', 'Incentivos', '#ebbe28', 'Carregar o piano', 'A sustentação do trabalho silencioso que garante a entrega de toda a equipe.', 'Conte quando fazer bem feito o trabalho de base rendeu ainda mais demanda. O que te manteve motivado(a) ou te fez recuar?'),
  ('I07', 'Incentivos', '#ebbe28', 'Fôlego', 'A motivação intrínseca de servir ao público com propósito além de prêmios.', 'Conte um projeto desafiador que você faria de novo mesmo sem nenhum reconhecimento formal e qual foi o motivo.'),
  ('I08', 'Incentivos', '#ebbe28', 'Dar um jeito', 'A capacidade de construir soluções criativas mesmo com recursos escassos.', 'Conte como você viabilizou uma entrega relevante sem orçamento ou equipe dedicada — ou o que morreu por essa falta.'),
  ('I09', 'Incentivos', '#ebbe28', 'Ponte', 'A conexão institucional que destrava: uma pessoa um órgão ou um parceiro-chave.', 'Conte sobre uma ponte que mudou o rumo de um trabalho seu. Quem foi a figura-chave que conectou as pontas?'),
  ('I10', 'Incentivos', '#ebbe28', 'Vitrine', 'Dar visibilidade ao que funciona para que outros órgãos adaptem e usem.', 'Conte quando compartilhar publicamente um trabalho mudou o destino dele — ou um bom projeto que morreu no anonimato.'),
  ('N01', 'Normas', '#0e3e66', 'Gambiarra', 'A solução engenhosa que funciona antes de virar regra ou processo formal.', 'Conte uma gambiarra sua que merecia virar norma. Ou uma que deu errado e mostrou onde a regra fazia falta.'),
  ('N02', 'Normas', '#0e3e66', 'Carimbo', 'A exigência formal que pode proteger a decisão ou apenas burocratizar o processo.', 'Conte uma vez em que uma etapa burocrática salvou seu trabalho — ou uma em que o carimbo só serviu para atrapalhar.'),
  ('N03', 'Normas', '#0e3e66', 'Piloto', 'Testar pequeno antes de fazer grande: o erro barato que evita o erro caro.', 'Conte um teste que você realizou em escala pequena. Ele cresceu, foi descontinuado ou ficou no meio do caminho?'),
  ('N04', 'Normas', '#0e3e66', 'Tropeço', 'Quem ginga tropeça: o erro como etapa natural e pedagógica da inovação.', 'Conte um tropeço seu tentando fazer diferente. O que ele ensinou, e como o aprendizado foi compartilhado?'),
  ('N05', 'Normas', '#0e3e66', 'Brecha', 'O espaço legítimo dentro da regra para fazer o certo de um jeito novo.', 'Conte uma vez em que você encontrou na norma uma brecha para inovar. Ou procurou, não encontrou, e o que fez então.'),
  ('N06', 'Normas', '#0e3e66', 'Letra miúda', 'O detalhe normativo que ninguém lê, mas que define a viabilidade da ideia.', 'Conte a vez em que a letra miúda te surpreendeu, ou em que conhecê-la a fundo salvou o projeto.'),
  ('N07', 'Normas', '#0e3e66', 'Virou rotina', 'A inovação que começou como teste e transformou a prática do dia a dia.', 'Conte algo que nasceu como experiência piloto e hoje é rotina no seu órgão. O que fez a ideia se consolidar?'),
  ('N08', 'Normas', '#0e3e66', 'Engavetado', 'O projeto que parou na gaveta à espera de assinatura conjuntura ou parceiro.', 'Conte um projeto importante seu que foi engavetado. Ele saiu de lá? O que faltou e o que você faria diferente?'),
  ('N09', 'Normas', '#0e3e66', 'Combinado', 'O alinhamento compartilhado que pactua expectativas e evita retrabalho.', 'Conte um combinado formal ou informal que evitou um problema grave — ou a confusão que veio por faltar alinhamento prévio.'),
  ('N10', 'Normas', '#0e3e66', 'Papel passado', 'Registrar formalmente para dar segurança jurídica e continuidade ao projeto.', 'Conte uma vez em que registrar ou normatizar algo (ou deixar de registrar) mudou decisivamente o rumo da história.'),
  ('C01', 'Gestão de capacidades', '#0a6637', 'Maresia ou maremoto?', 'A capacidade prospectiva de antecipar tendências antes que virem crises.', 'Conte quando a equipe percebeu uma onda de mudança a tempo de se preparar — ou quando a falta de prontidão gerou emergência.'),
  ('C02', 'Gestão de capacidades', '#0a6637', 'Chutômetro', 'O risco de formular soluções sem dados diagnósticos ou evidências sólidas.', 'Conte uma decisão que mudou de rumo após a análise de dados concretos — ou uma que foi no chute e o preço pago por isso.'),
  ('C03', 'Gestão de capacidades', '#0a6637', 'Aproveitar a deixa', 'A prontidão institucional para transformar janelas de oportunidade em inovação.', 'Conte uma oportunidade (edital conjuntura ou nova demanda) que seu órgão aproveitou com agilidade — ou uma que passou por falta de preparo.'),
  ('C04', 'Gestão de capacidades', '#0a6637', 'Jogo de cintura', 'A flexibilidade dinâmica de reorganizar processos e equipes ante novas realidades.', 'Conte quando sua equipe precisou se reinventar com agilidade para responder a uma nova exigência. O que foi mais desafiador?'),
  ('C05', 'Gestão de capacidades', '#0a6637', 'E depois?', 'A avaliação pós-entrega que analisa acertos e erros para consolidar aprendizado.', 'Conte quando a equipe parou após uma entrega para avaliar o que funcionou e o que ajustar. O que melhorou dali em diante?'),
  ('C06', 'Gestão de capacidades', '#0a6637', 'Termômetro', 'Medir e avaliar para aprender e colaborar não para punir ou ranquear.', 'Conte uma medição ou indicador que ajudou o trabalho a melhorar de verdade — ou uma métrica que só gerou distorção e medo.'),
  ('C07', 'Gestão de capacidades', '#0a6637', 'Ponto de partida', 'O reconhecimento das diferentes capacidades estruturais entre órgãos públicos.', 'Conte uma situação em que disparidades de estrutura entre áreas ficaram evidentes na prática. O que ajudaria a equilibrar?'),
  ('C08', 'Gestão de capacidades', '#0a6637', 'Saiu e levou tudo', 'O risco de concentrar o saber em uma pessoa só sem institucionalizar na equipe.', 'Conte quando a saída de alguém levou junto um conhecimento técnico insubstituível. O que teria evitado essa perda?'),
  ('C09', 'Gestão de capacidades', '#0a6637', 'Com que time?', 'Inovar exige estrutura básica ferramentas certas e competências diversas.', 'Conte quando faltou estrutura mínima para uma boa ideia andar — ou quando a equipe e a ferramenta certas fizeram a diferença.'),
  ('C10', 'Gestão de capacidades', '#0a6637', 'Espelho', 'O diagnóstico honesto sobre as próprias forças e fraquezas para evoluir.', 'Conte quando sua equipe se olhou no espelho com honestidade e reconheceu um ponto fraco. O que foi feito a partir disso?'),
  ('A01', 'Ambiência', '#d14b2a', 'Pisar em ovos', 'O clima de desconfiança em que o medo do erro paralisa a iniciativa.', 'Conte um ambiente de trabalho onde você pisava em ovos. O que causava isso? E um onde você podia ser autêntico(a)?'),
  ('A02', 'Ambiência', '#d14b2a', 'Elefante na sala', 'O problema evidente que todos enxergam mas ninguém tem coragem de nomear.', 'Conte uma vez em que alguém nomeou com coragem o elefante na sala. O que mudou depois? E quando ninguém falou qual foi o custo?'),
  ('A03', 'Ambiência', '#d14b2a', 'Guardei pra mim', 'A ideia ou o alerta que ficou retido porque falar custava caro demais.', 'Conte uma ideia ou preocupação que você guardou para si por receio da reação. O que teria mudado se houvesse abertura?'),
  ('A04', 'Ambiência', '#d14b2a', 'Portas abertas', 'A liderança acessível e empática que acolhe a inovação com apoio efetivo.', 'Conte como a presença de uma chefia de portas verdadeiramente abertas (ou fechadas) impactou a segurança da equipe.'),
  ('A05', 'Ambiência', '#d14b2a', 'Não sei', 'A segurança psicológica de admitir limites como ponto de partida para aprender.', 'Conte quando um não sei ou me desculpe dito em público abriu espaço para cooperação — ou quando o orgulho custou caro.'),
  ('A06', 'Ambiência', '#d14b2a', 'Dar um toque', 'O feedback construtivo e transparente que ajusta a rota com respeito e cuidado.', 'Conte um feedback sincero que você recebeu e aprimorou seu trabalho — ou aquele retorno que faltou e fez falta.'),
  ('A07', 'Ambiência', '#d14b2a', 'Fazer o que fala', 'A coerência entre o discurso institucional e as atitudes práticas da gestão.', 'Conte uma atitude coerente da liderança que gerou forte confiança na equipe — ou uma quebra de discurso que desmobilizou o time.'),
  ('A08', 'Ambiência', '#d14b2a', 'Prego que se destaca', 'Na cultura de inovação quem se destaca recebe apoio e abre caminhos.', 'Conte quando propor algo novo te rendeu apoio e oportunidades — ou quando gerou resistência e o que isso ensinou.'),
  ('A09', 'Ambiência', '#d14b2a', 'Pertencimento', 'Sentir-se parte integrante e corresponsável por uma missão pública maior.', 'Conte quando você se sentiu verdadeiramente acolhido(a) e parte do propósito do órgão. O que gerou esse sentimento?'),
  ('A10', 'Ambiência', '#d14b2a', 'Respiro', 'O tempo protegido na rotina para pensar se inspirar e inovar com clareza.', 'Conte quando uma pausa estratégica na rotina rendeu uma excelente solução — ou o que você criaria com um tempo livre semanal.')
